import{_ as a,c as o,o as t,a0 as i}from"./chunks/framework.oTSD2LDJ.js";const u=JSON.parse('{"title":"UniDeskWindow","description":"","frontmatter":{"title":"UniDeskWindow","editLink":true},"headers":[],"relativePath":"en/controls-reference/UniDeskWindow.md","filePath":"en/controls-reference/UniDeskWindow.md"}'),r={name:"en/controls-reference/UniDeskWindow.md"};function s(n,e,l,d,h,p){return t(),o("div",null,e[0]||(e[0]=[i('<h1 id="unideskwindow-type" tabindex="-1">UniDeskWindow Type <a class="header-anchor" href="#unideskwindow-type" aria-label="Permalink to &quot;UniDeskWindow Type&quot;">​</a></h1><p>The base window control of Uniquenium. Built on top of <code>QtQuick.Window</code>, it adds frameless rendering, Acrylic blur, a custom AppBar, and a built-in info bar. It is the base class for all application windows (settings window, component manager window, page manager window, etc.).</p><table tabindex="0"><thead><tr><th>Control Type</th><th>Visual Control</th></tr></thead><tbody><tr><td>Source File</td><td><code>UniDesk/Controls/UniDeskWindow.qml</code></td></tr><tr><td>Inherits</td><td>QtQuick Window</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="default-property-alias-contentdata" tabindex="-1"><code>default property alias contentData</code> <a class="header-anchor" href="#default-property-alias-contentdata" aria-label="Permalink to &quot;`default property alias contentData`&quot;">​</a></h3><p>Default property, pointing to the main content area <code>layout_content.data</code>. Child items placed directly inside a <code>UniDeskWindow { ... }</code> are automatically hosted in this area.</p><h3 id="property-string-windowicon" tabindex="-1"><code>property string windowIcon</code> <a class="header-anchor" href="#property-string-windowicon" aria-label="Permalink to &quot;`property string windowIcon`&quot;">​</a></h3><p>Window icon (shown on the left side of the AppBar).</p><h3 id="property-int-launchmode-unideskwindowtype-standard" tabindex="-1"><code>property int launchMode: UniDeskWindowType.Standard</code> <a class="header-anchor" href="#property-int-launchmode-unideskwindowtype-standard" aria-label="Permalink to &quot;`property int launchMode: UniDeskWindowType.Standard`&quot;">​</a></h3><p>Window launch mode (defined by the <code>UniDeskWindowType</code> enumeration).</p><h3 id="property-var-argument" tabindex="-1"><code>property var argument: ({})</code> <a class="header-anchor" href="#property-var-argument" aria-label="Permalink to &quot;`property var argument: ({})`&quot;">​</a></h3><p>Parameters passed in at window creation. They are dispatched to subclasses via the <code>initArgument(argument)</code> signal in <code>Component.onCompleted</code>.</p><h3 id="property-var-background" tabindex="-1"><code>property var background</code> <a class="header-anchor" href="#property-var-background" aria-label="Permalink to &quot;`property var background`&quot;">​</a></h3><p>Window background. Defaults to the internal <code>com_background</code> component (system wallpaper + Acrylic blur).</p><h3 id="property-bool-fixsize-false" tabindex="-1"><code>property bool fixSize: false</code> <a class="header-anchor" href="#property-bool-fixsize-false" aria-label="Permalink to &quot;`property bool fixSize: false`&quot;">​</a></h3><p>Whether to lock the window size. When enabled, the window cannot be resized by dragging and maximize/minimize buttons are disabled.</p><h3 id="property-bool-fitsappbarwindows-false" tabindex="-1"><code>property bool fitsAppBarWindows: false</code> <a class="header-anchor" href="#property-bool-fitsappbarwindows-false" aria-label="Permalink to &quot;`property bool fitsAppBarWindows: false`&quot;">​</a></h3><p>Whether the AppBar area aligns with the content area (used when the AppBar is embedded in the system title bar).</p><h3 id="property-var-tintopacity" tabindex="-1"><code>property var tintOpacity</code> <a class="header-anchor" href="#property-var-tintopacity" aria-label="Permalink to &quot;`property var tintOpacity`&quot;">​</a></h3><p>Opacity of the Acrylic background. Defaults to <code>0.50</code> in dark mode and <code>0.75</code> in light mode.</p><h3 id="property-int-blurradius-80" tabindex="-1"><code>property int blurRadius: 80</code> <a class="header-anchor" href="#property-int-blurradius-80" aria-label="Permalink to &quot;`property int blurRadius: 80`&quot;">​</a></h3><p>Blur radius of the Acrylic effect.</p><h3 id="property-var-windowvisibility" tabindex="-1"><code>property var windowVisibility</code> <a class="header-anchor" href="#property-var-windowvisibility" aria-label="Permalink to &quot;`property var windowVisibility`&quot;">​</a></h3><p>Alias of the window <code>visibility</code> property (used for QML binding).</p><h3 id="property-alias-effect-frameless-effect" tabindex="-1"><code>property alias effect: frameless.effect</code> <a class="header-anchor" href="#property-alias-effect-frameless-effect" aria-label="Permalink to &quot;`property alias effect: frameless.effect`&quot;">​</a></h3><p>Current effect used by the frameless window (points to <code>UniDeskFrameless.effect</code>).</p><h3 id="readonly-property-alias-effective-frameless-effective" tabindex="-1"><code>readonly property alias effective: frameless.effective</code> <a class="header-anchor" href="#readonly-property-alias-effective-frameless-effective" aria-label="Permalink to &quot;`readonly property alias effective: frameless.effective`&quot;">​</a></h3><p>Whether the current effect is active (read-only).</p><h3 id="readonly-property-alias-availableeffects-frameless-availableeffects" tabindex="-1"><code>readonly property alias availableEffects: frameless.availableEffects</code> <a class="header-anchor" href="#readonly-property-alias-availableeffects-frameless-availableeffects" aria-label="Permalink to &quot;`readonly property alias availableEffects: frameless.availableEffects`&quot;">​</a></h3><p>List of available effects (read-only).</p><h3 id="property-item-appbar" tabindex="-1"><code>property Item appBar</code> <a class="header-anchor" href="#property-item-appbar" aria-label="Permalink to &quot;`property Item appBar`&quot;">​</a></h3><p>Custom window title bar (a <code>UniDeskAppBar</code> instance is created by default and auto-updated with the window title, icon and button visibility).</p><h3 id="property-color-backgroundcolor" tabindex="-1"><code>property color backgroundColor</code> <a class="header-anchor" href="#property-color-backgroundcolor" aria-label="Permalink to &quot;`property color backgroundColor`&quot;">​</a></h3><p>Window background color, automatically computed based on theme (light/dark), active state, and whether the Acrylic effect is enabled.</p><h3 id="property-bool-staytop-false" tabindex="-1"><code>property bool stayTop: false</code> <a class="header-anchor" href="#property-bool-staytop-false" aria-label="Permalink to &quot;`property bool stayTop: false`&quot;">​</a></h3><p>Whether the window should stay on top.</p><h3 id="property-bool-showdark-false" tabindex="-1"><code>property bool showDark: false</code> <a class="header-anchor" href="#property-bool-showdark-false" aria-label="Permalink to &quot;`property bool showDark: false`&quot;">​</a></h3><p>Whether to force the window into dark mode (affects AppBar buttons and border color).</p><h3 id="property-bool-showclose-true" tabindex="-1"><code>property bool showClose: true</code> <a class="header-anchor" href="#property-bool-showclose-true" aria-label="Permalink to &quot;`property bool showClose: true`&quot;">​</a></h3><p>Whether to show the close button.</p><h3 id="property-bool-showminimize-true" tabindex="-1"><code>property bool showMinimize: true</code> <a class="header-anchor" href="#property-bool-showminimize-true" aria-label="Permalink to &quot;`property bool showMinimize: true`&quot;">​</a></h3><p>Whether to show the minimize button.</p><h3 id="property-bool-showmaximize-true" tabindex="-1"><code>property bool showMaximize: true</code> <a class="header-anchor" href="#property-bool-showmaximize-true" aria-label="Permalink to &quot;`property bool showMaximize: true`&quot;">​</a></h3><p>Whether to show the maximize/restore button.</p><h3 id="property-bool-showstaytop-false" tabindex="-1"><code>property bool showStayTop: false</code> <a class="header-anchor" href="#property-bool-showstaytop-false" aria-label="Permalink to &quot;`property bool showStayTop: false`&quot;">​</a></h3><p>Whether to show the stay-on-top button.</p><h3 id="property-bool-automaximize-false" tabindex="-1"><code>property bool autoMaximize: false</code> <a class="header-anchor" href="#property-bool-automaximize-false" aria-label="Permalink to &quot;`property bool autoMaximize: false`&quot;">​</a></h3><p>Whether to automatically maximize the window when created.</p><h3 id="property-bool-autovisible-true" tabindex="-1"><code>property bool autoVisible: true</code> <a class="header-anchor" href="#property-bool-autovisible-true" aria-label="Permalink to &quot;`property bool autoVisible: true`&quot;">​</a></h3><p>Whether to call <code>show()</code> automatically after the window is created.</p><h3 id="property-bool-autocenter-true" tabindex="-1"><code>property bool autoCenter: true</code> <a class="header-anchor" href="#property-bool-autocenter-true" aria-label="Permalink to &quot;`property bool autoCenter: true`&quot;">​</a></h3><p>Whether to automatically center the window on the screen when created.</p><h3 id="property-bool-autodestroy-true" tabindex="-1"><code>property bool autoDestroy: true</code> <a class="header-anchor" href="#property-bool-autodestroy-true" aria-label="Permalink to &quot;`property bool autoDestroy: true`&quot;">​</a></h3><p>Whether to destroy the window on close. If set to <code>false</code>, the window is hidden (<code>visibility = Hidden</code>) instead.</p><h3 id="property-bool-usesystemappbar" tabindex="-1"><code>property bool useSystemAppBar</code> <a class="header-anchor" href="#property-bool-usesystemappbar" aria-label="Permalink to &quot;`property bool useSystemAppBar`&quot;">​</a></h3><p>Whether to use the system title bar (assigned by subclasses in <code>Component.onCompleted</code>, default is <code>false</code>).</p><h3 id="property-int-margins-0" tabindex="-1"><code>property int __margins: 0</code> <a class="header-anchor" href="#property-int-margins-0" aria-label="Permalink to &quot;`property int __margins: 0`&quot;">​</a></h3><p>Inner padding between the window content area and the window border.</p><h3 id="property-color-resizebordercolor" tabindex="-1"><code>property color resizeBorderColor</code> <a class="header-anchor" href="#property-color-resizebordercolor" aria-label="Permalink to &quot;`property color resizeBorderColor`&quot;">​</a></h3><p>Window border color, automatically computed based on theme and active state.</p><h3 id="property-int-resizeborderwidth-1" tabindex="-1"><code>property int resizeBorderWidth: 1</code> <a class="header-anchor" href="#property-int-resizeborderwidth-1" aria-label="Permalink to &quot;`property int resizeBorderWidth: 1`&quot;">​</a></h3><p>Width of the window border and also the hit area for border dragging.</p><h3 id="property-var-closelistener" tabindex="-1"><code>property var closeListener</code> <a class="header-anchor" href="#property-var-closelistener" aria-label="Permalink to &quot;`property var closeListener`&quot;">​</a></h3><p>Close event callback with the signature <code>function(event)</code>. When <code>autoDestroy=false</code>, it intercepts the close event and hides the window instead of destroying it.</p><h3 id="property-bool-hideshadow-false" tabindex="-1"><code>property bool _hideShadow: false</code> <a class="header-anchor" href="#property-bool-hideshadow-false" aria-label="Permalink to &quot;`property bool _hideShadow: false`&quot;">​</a></h3><p>Whether to hide the window shadow.</p><h2 id="signals" tabindex="-1">Signals <a class="header-anchor" href="#signals" aria-label="Permalink to &quot;Signals&quot;">​</a></h2><h3 id="signal-focusout" tabindex="-1"><code>signal focusOut()</code> <a class="header-anchor" href="#signal-focusout" aria-label="Permalink to &quot;`signal focusOut()`&quot;">​</a></h3><p>Forwarded by the internal <code>UniDeskFrameless</code> when the window loses focus.</p><h3 id="signal-initargument-var-argument" tabindex="-1"><code>signal initArgument(var argument)</code> <a class="header-anchor" href="#signal-initargument-var-argument" aria-label="Permalink to &quot;`signal initArgument(var argument)`&quot;">​</a></h3><p>Emitted after the window is initialized. The argument is the <code>argument</code> passed at construction, used by subclasses to receive startup parameters.</p><h3 id="signal-lazyload" tabindex="-1"><code>signal lazyLoad()</code> <a class="header-anchor" href="#signal-lazyload" aria-label="Permalink to &quot;`signal lazyLoad()`&quot;">​</a></h3><p>Emitted on the first show of the window (lazy-load trigger), used to delay-load heavy resources.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="function-movewindowtodesktopcenter" tabindex="-1"><code>function moveWindowToDesktopCenter()</code> <a class="header-anchor" href="#function-movewindowtodesktopcenter" aria-label="Permalink to &quot;`function moveWindowToDesktopCenter()`&quot;">​</a></h3><p>Move the window to the center of the current desktop&#39;s available area.</p><h3 id="function-fixwindowsize" tabindex="-1"><code>function fixWindowSize()</code> <a class="header-anchor" href="#function-fixwindowsize" aria-label="Permalink to &quot;`function fixWindowSize()`&quot;">​</a></h3><p>Lock the window&#39;s maximum/minimum size according to the <code>fixSize</code> property.</p><h3 id="function-setresult-data" tabindex="-1"><code>function setResult(data)</code> <a class="header-anchor" href="#function-setresult-data" aria-label="Permalink to &quot;`function setResult(data)`&quot;">​</a></h3><p>Return a result to the window registrar (<code>_windowRegister</code>).</p><h3 id="function-showmaximized-function-showminimized-function-shownormal" tabindex="-1"><code>function showMaximized()</code> / <code>function showMinimized()</code> / <code>function showNormal()</code> <a class="header-anchor" href="#function-showmaximized-function-showminimized-function-shownormal" aria-label="Permalink to &quot;`function showMaximized()` / `function showMinimized()` / `function showNormal()`&quot;">​</a></h3><p>Explicitly switch the window to maximized / minimized / normal state.</p><h3 id="function-sethittestvisible-val" tabindex="-1"><code>function setHitTestVisible(val)</code> <a class="header-anchor" href="#function-sethittestvisible-val" aria-label="Permalink to &quot;`function setHitTestVisible(val)`&quot;">​</a></h3><p>Set whether the window receives mouse hit-testing (transparency toggle).</p><h3 id="function-deletelater" tabindex="-1"><code>function deleteLater()</code> <a class="header-anchor" href="#function-deletelater" aria-label="Permalink to &quot;`function deleteLater()`&quot;">​</a></h3><p>Defer-destroy the window (eventually calls <code>UniDeskUtils.deleteLater</code>).</p><h3 id="function-containeritem" tabindex="-1"><code>function containerItem()</code> <a class="header-anchor" href="#function-containeritem" aria-label="Permalink to &quot;`function containerItem()`&quot;">​</a></h3><p>Return the root container Item of the window (<code>layout_container</code>), useful for dynamically mounting child components.</p><h3 id="function-showactivate" tabindex="-1"><code>function showActivate()</code> <a class="header-anchor" href="#function-showactivate" aria-label="Permalink to &quot;`function showActivate()`&quot;">​</a></h3><p>If the window is visible, call <code>requestActivate()</code>; otherwise call <code>show()</code>.</p><h3 id="function-showsuccess-text-duration-moremsg-function-showinfo-function-showwarning-function-showerror" tabindex="-1"><code>function showSuccess(text, duration, moremsg)</code> / <code>function showInfo(...)</code> / <code>function showWarning(...)</code> / <code>function showError(...)</code> <a class="header-anchor" href="#function-showsuccess-text-duration-moremsg-function-showinfo-function-showwarning-function-showerror" aria-label="Permalink to &quot;`function showSuccess(text, duration, moremsg)` / `function showInfo(...)` / `function showWarning(...)` / `function showError(...)`&quot;">​</a></h3><p>Show a temporary message via the built-in <code>UniDeskInfoBar</code>.</p><h3 id="function-clearallinfo" tabindex="-1"><code>function clearAllInfo()</code> <a class="header-anchor" href="#function-clearallinfo" aria-label="Permalink to &quot;`function clearAllInfo()`&quot;">​</a></h3><p>Clear all info messages currently displayed in the window.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">UniDeskWindow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;My Window&quot;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    windowIcon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;qrc:/icons/app.png&quot;</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    argument</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { userId: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    autoCenter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    autoMaximize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    stayTop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    showDark</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: UniDeskGlobals.isLight </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    onInitArgument</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Startup parameters:&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, argument)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Column</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">        anchors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">centerIn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: parent</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello Uniquenium&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><code>UniDeskWindow</code> works together with <code>UniDeskFrameless</code> to provide true frameless windows. Dragging, hit-testing and Acrylic effects are all handled by the latter.</li><li>The window background uses the current system wallpaper by default (<code>UniDeskTools.get_system_wallpaper()</code>) with a <code>UniDeskAcrylic</code> blur on top.</li><li>On Wayland or in software rendering mode, it automatically falls back to a solid color background (<code>UniDeskUtils.isSoftware()</code>).</li><li>The closing behavior is controlled by <code>closeListener</code>: when <code>autoDestroy=true</code>, the window is destroyed directly; when <code>autoDestroy=false</code>, it is only hidden, which is useful for long-lived tool windows.</li></ul>',98)]))}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
